import { resolvePackPaths } from "../packs.js";
let modulePromise = null;
function ensureModule(base) {
    if (!modulePromise) {
        modulePromise = (async () => {
            importScripts(base + "sherpa-onnx-wasm-web.js", base + "sherpa-onnx-tts.js");
            return SherpaOnnx({ locateFile: (p) => base + p, print: (s) => console.log("[sherpa]", s), printErr: (s) => console.warn("[sherpa]", s) });
        })().catch((e) => { modulePromise = null; throw e; });
    }
    return modulePromise;
}
export function createSherpaBackend() {
    let tts = null;
    let ec = null;
    return {
        async load({ engineBase, manifests, files }) {
            const m = manifests[0]; // sherpa 的音色 = 一个包：引擎配置写在它的清单里
            const Module = await ensureModule(engineBase);
            const conf = m.engineConfig;
            if (conf.kind !== "sherpa-offline-tts")
                throw new Error(`pack ${m.slug}: engineConfig.kind is "${String(conf.kind)}", expected "sherpa-offline-tts"`);
            const dir = `/packs/${m.slug}`;
            const mkdirp = (p) => { let cur = ""; for (const part of p.split("/").filter(Boolean)) {
                cur += "/" + part;
                try {
                    Module.FS.mkdir(cur);
                }
                catch { /* exists */ }
            } };
            mkdirp(dir);
            for (const [path, bytes] of files) {
                const slash = path.lastIndexOf("/");
                const parent = slash < 0 ? dir : `${dir}/${path.slice(0, slash)}`;
                if (slash >= 0)
                    mkdirp(parent);
                try {
                    Module.FS.unlink(`${dir}/${path}`);
                }
                catch { /* 上次没删干净的同名文件 */ }
                Module.FS.createDataFile(parent, slash < 0 ? path : path.slice(slash + 1), bytes, true, true, true);
            }
            const created = new OfflineTts(resolvePackPaths(conf.config, dir, [...files.keys()]), Module);
            for (const name of conf.unlinkAfterLoad ?? []) {
                try {
                    Module.FS.unlink(`${dir}/${name}`);
                }
                catch { /* ignore */ }
            }
            if (!created.handle)
                throw new Error("voice engine creation failed (see [sherpa] console output)");
            tts = created;
            ec = conf;
            return { sampleRate: created.sampleRate, speakers: created.numSpeakers };
        },
        synth(text, o) {
            if (!tts || !ec)
                throw new Error("no voice loaded");
            const r = tts.generateWithConfig(text, {
                sid: o.speaker, speed: o.speed,
                numSteps: ec.generate?.numSteps, silenceScale: ec.generate?.silenceScale ?? 0.2,
                extra: ec.passLang ? { lang: o.lang } : undefined,
            });
            return { samples: r.samples, sampleRate: r.sampleRate };
        },
        unload() { if (tts) {
            try {
                tts.free();
            }
            catch { /* ignore */ }
            tts = null;
            ec = null;
        } },
    };
}
